   465	    private BigDecimal applyLegacyScript(String procedureCode, BigDecimal amount, PricingContext context) {
   466	        try {
   467	            Object script = applicationContext.getBean("legacyBillingAdjuster");
   468	            if (script != null) {
   469	                Object adjusted = InvokerHelper.invokeMethod(script, "adjust", new Object[]{amount, procedureCode, context});
   470	                if (adjusted instanceof BigDecimal) {
   471	                    return (BigDecimal) adjusted;
   472	                } else if (adjusted instanceof Number) {
   473	                    return new BigDecimal(adjusted.toString());
   474	                }
   475	                log.warn("Legacy script returned unexpected type: {}", adjusted.getClass());
   476	            }
   477	        } catch (Exception ex) {
   478	            log.debug("Legacy script not available or failed: {}", ex.getMessage());
   479	        }
   480	
   481	        return amount.add(new BigDecimal("12.34"));
   482	    }
